8	/**
9	 * Normalizes a raw Claude CLI stream-json event into a harness event.
10	 * Returns null for events that should be ignored (unknown types, non-init system events).
11	 */
12	export function normalizeClaude(raw: unknown): NormalizedEvent | null {
13	  if (raw == null || typeof raw !== 'object') return null
14	
15	  const msg = raw as Record<string, unknown>
16	
17	  switch (msg.type) {
18	    case 'system': {
19	      if (msg.subtype === 'init') {
20	        return {
21	          type: 'run:ready',
22	          data: {
23	            resumeId: msg.session_id as string,
24	            model: msg.model as string | undefined,
25	            tools: msg.tools as unknown[] | undefined,
26	            cwd: msg.cwd as string | undefined,
27	            mcpServers: msg.mcp_servers as unknown[] | undefined,
28	            permissionMode: msg.permissionMode as string | undefined,
29	          },
30	        }
31	      }
32	      if (msg.subtype === 'compact_boundary') {
33	        return {
34	          type: 'turn:end',
35	          data: {
36	            compact: true,
37	            trigger: (msg.compact_metadata as Record<string, unknown> | undefined)?.trigger,
38	          },
39	        }
40	      }
41	      return null
42	    }
43	
44	    case 'assistant': {
45	      const message = msg.message as Record<string, unknown> | undefined
46	      if (!message) return null
47	      const content = message.content as unknown[] | undefined
48	      if (!content) return null
49	      return {
50	        type: 'content',
51	        data: { blocks: normalizeContentBlocks(content) },
52	      }
53	    }
54	
55	    case 'user': {
56	      const message = msg.message as Record<string, unknown> | undefined
57	      if (!message) return null
58	      const content = message.content as unknown[] | undefined
59	      if (!content) return null
60	      return {
61	        type: 'result',
62	        data: { blocks: normalizeResultBlocks(content) },
63	      }
64	    }
65	
66	    case 'result': {
67	      return {
68	        type: 'turn:end',
69	        data: {
70	          usage: msg.usage as Record<string, unknown> | undefined,
71	          duration: msg.duration_ms as number | undefined,
72	        },
73	      }
74	    }
75	
76	    default:
77	      return null
78	  }
79	}
80	
81	function normalizeContentBlocks(blocks: unknown[]): ContentBlock[] {
82	  const result: ContentBlock[] = []
83	  for (const block of blocks) {
84	    if (block == null || typeof block !== 'object') continue
85	    const b = block as Record<string, unknown>
86	    switch (b.type) {
87	      case 'text':
88	        result.push({ type: 'text', text: b.text as string })
