93	      case 'tool_use':
94	        result.push({
95	          type: 'tool_use',
96	          id: b.id as string,
97	          name: b.name as string,
98	          input: b.input,
99	        })
100	        break
101	      // Unknown block types are silently dropped
102	    }
103	  }
104	  return result
105	}
