2	 * Cassette recording and replay for ProcessAdapter.
3	 *
4	 * Record real CLI sessions, replay them deterministically in tests.
5	 * Guarantees test event streams match real CLI output byte-for-byte (at the
6	 * line level — chunking fidelity is JsonLinesParser's concern).
7	 *
8	 * Recording: CassetteRecorder wraps any ProcessAdapter, tees stdout/stdin to
9	 * a JSONL recording while passing events through normally.
10	 *
11	 * Replay: CassetteAdapter implements ProcessAdapter, replaying a recording as
12	 * if a live process were emitting lines. Preserves real timing between stdout
13	 * events. At stdin markers, pauses until write() is called (skipping user
14	 * think-time — only CLI processing time after stdin is preserved).
15	 */
16	
17	import type { ProcessAdapter, ProcessHandle, SpawnConfig } from './process-adapter.js'
18	
19	// ---- Cassette entry types ----
20	
21	export interface CassetteMeta {
22	  type: 'meta'
23	  ts: 0
24	  format: 1
25	}
26	
27	export interface CassetteStdout {
28	  type: 'stdout'
29	  ts: number
30	  data: string
31	}
32	
33	export interface CassetteStdin {
34	  type: 'stdin'
35	  ts: number
36	  data: string
37	}
38	
39	export interface CassetteExit {
40	  type: 'exit'
41	  ts: number
42	  code: number
43	  signal?: string
44	}
45	
46	export type CassetteEntry = CassetteMeta | CassetteStdout | CassetteStdin | CassetteExit
47	
48	// ---- Serialization ----
49	
50	export function serializeCassette(entries: CassetteEntry[]): string {
51	  return entries.map(e => JSON.stringify(e)).join('\n') + '\n'
52	}
53	
54	export function parseCassette(content: string): CassetteEntry[] {
55	  return content
56	    .trim()
57	    .split('\n')
58	    .filter(line => line.trim())
59	    .map(line => JSON.parse(line) as CassetteEntry)
60	}
61	
62	// ---- CassetteRecorder ----
63	
64	/**
65	 * Wraps a ProcessAdapter to record stdout, stdin, and exit events.
66	 * Use it as a drop-in replacement — it delegates to the inner adapter and
67	 * captures everything that flows through.
68	 *
69	 * After the session, retrieve the recording with `getRecording()`.
70	 */
71	export class CassetteRecorder implements ProcessAdapter {
72	  private inner: ProcessAdapter
73	  private recordings: CassetteEntry[][] = []
74	
75	  constructor(inner: ProcessAdapter) {
76	    this.inner = inner
77	  }
78	
79	  async spawn(config: SpawnConfig): Promise<ProcessHandle> {
80	    const entries: CassetteEntry[] = [{ type: 'meta', ts: 0, format: 1 }]
81	    const startTime = Date.now()
82	    this.recordings.push(entries)
83	
84	    const handle = await this.inner.spawn(config)
85	
86	    // Wrap stdout — record each line as it arrives
87	    const realStdout = handle.stdout
88	    const stdout: AsyncIterable<string> = {
89	      [Symbol.asyncIterator]() {
90	        const iter = realStdout[Symbol.asyncIterator]()
91	        return {
92	          async next() {
93	            const result = await iter.next()
94	            if (!result.done) {
95	              entries.push({
96	                type: 'stdout',
97	                ts: Date.now() - startTime,
98	                data: result.value,
99	              })
100	            }
101	            return result
102	          },
103	        }
104	      },
105	    }
106	
107	    // Wrap write — record stdin
108	    const realWrite = handle.write.bind(handle)
109	    const write = (input: string) => {
110	      entries.push({
111	        type: 'stdin',
112	        ts: Date.now() - startTime,
113	        data: input,
114	      })
115	      realWrite(input)
116	    }
117	
118	    // Wrap exited — record exit
119	    const exited = handle.exited.then(result => {
120	      entries.push({
121	        type: 'exit',
122	        ts: Date.now() - startTime,
123	        code: result.code,
124	        signal: result.signal,
125	      })
126	      return result
127	    })
128	
129	    return {
130	      stdout,
131	      write,
132	      signal: handle.signal.bind(handle),
133	      exited,
134	      get alive() { return handle.alive },
135	      pid: handle.pid,
136	      processId: handle.processId,
137	    }
138	  }
139	
140	  /** Retrieve the recording from the nth spawn (default: most recent). */
141	  getRecording(index?: number): CassetteEntry[] {
142	    const i = index ?? this.recordings.length - 1
143	    return this.recordings[i] ?? []
144	  }
145	
146	  get recordingCount(): number {
147	    return this.recordings.length
148	  }
149	}
150	
151	// ---- CassetteAdapter (replay) ----
152	
153	/**
154	 * Replays a cassette recording as a ProcessAdapter.
155	 *
156	 * Stdout lines are emitted with their original inter-event timing.
157	 * At stdin markers, playback pauses until write() is called — this skips
158	 * the original user think-time but preserves CLI processing time (the delay
159	 * from stdin to the next stdout event).
160	 *
161	 * No fallback: if no recording is provided, spawn() throws.
162	 */
163	export class CassetteAdapter implements ProcessAdapter {
164	  private entries: CassetteEntry[]
165	
166	  /** Stdin writes received during replay, for assertions. */
167	  readonly stdinWrites: string[] = []
168	
169	  /** Signals received during replay, for assertions. */
170	  readonly signals: NodeJS.Signals[] = []
171	
172	  constructor(entries: CassetteEntry[]) {
173	    if (entries.length === 0) {
174	      throw new Error('Cassette is empty — no recording to replay')
175	    }
176	    this.entries = entries
177	  }
178	
179	  static fromString(content: string): CassetteAdapter {
180	    return new CassetteAdapter(parseCassette(content))
181	  }
182	
183	  async spawn(_config: SpawnConfig): Promise<ProcessHandle> {
184	    const playbackEntries = this.entries.filter(e => e.type !== 'meta')
185	    const self = this
186	
187	    let alive = true
188	    let done = false
189	    const lineBuffer: string[] = []
190	    let lineResolve: ((value: IteratorResult<string>) => void) | null = null
191	    let stdinGate: (() => void) | null = null
192	    let stdinIndex = 0
193	    let resolveExit!: (value: { code: number; signal?: string }) => void
194	    const exited = new Promise<{ code: number; signal?: string }>(resolve => {
195	      resolveExit = resolve
196	    })
197	
198	    function emitLine(line: string) {
199	      if (lineResolve) {
200	        const resolve = lineResolve
201	        lineResolve = null
202	        resolve({ value: line, done: false })
203	      } else {
204	        lineBuffer.push(line)
205	      }
206	    }
207	
208	    function endStream() {
209	      alive = false
210	      done = true
211	      if (lineResolve) {
212	        const resolve = lineResolve
213	        lineResolve = null
214	        resolve({ value: undefined as unknown as string, done: true })
215	      }
216	    }
217	
218	    // Playback loop — runs asynchronously
219	    const playback = async () => {
220	      let lastTs = 0
221	
222	      for (const entry of playbackEntries) {
223	        if (done) break
224	
225	        if (entry.type === 'stdin') {
226	          // Don't apply the delay for stdin (skip user think-time).
227	          // Just wait for write() to be called.
228	          if (stdinIndex >= self.stdinWrites.length) {
229	            await new Promise<void>(resolve => { stdinGate = resolve })
230	          }
231	          stdinIndex++
232	          // Update lastTs so the delay to the NEXT event (stdout after stdin)
233	          // reflects real CLI processing time.
234	          lastTs = entry.ts
235	          continue
236	        }
237	
238	        // Apply delay between events (real CLI timing)
239	        const delay = entry.ts - lastTs
240	        if (delay > 0) {
241	          await new Promise<void>(resolve => setTimeout(resolve, delay))
242	        }
243	        lastTs = entry.ts
244	
245	        if (entry.type === 'stdout') {
246	          emitLine(entry.data)
247	        } else if (entry.type === 'exit') {
248	          endStream()
249	          resolveExit({ code: entry.code, signal: entry.signal })
250	          return
251	        }
252	      }
253	
254	      // No explicit exit entry — end naturally
255	      if (!done) {
256	        endStream()
257	        resolveExit({ code: 0 })
258	      }
259	    }
260	
261	    // Start playback (non-blocking)
262	    playback()
263	
264	    const stdout: AsyncIterable<string> = {
265	      [Symbol.asyncIterator]() {
266	        return {
267	          next(): Promise<IteratorResult<string>> {
268	            if (lineBuffer.length > 0) {
269	              return Promise.resolve({ value: lineBuffer.shift()!, done: false })
270	            }
271	            if (done) {
272	              return Promise.resolve({
273	                value: undefined as unknown as string,
274	                done: true,
275	              })
276	            }
277	            return new Promise(resolve => { lineResolve = resolve })
278	          },
279	        }
280	      },
281	    }
282	
283	    return {
284	      stdout,
285	      write(input: string) {
286	        self.stdinWrites.push(input)
287	        if (stdinGate) {
288	          const gate = stdinGate
289	          stdinGate = null
290	          gate()
291	        }
292	      },
293	      signal(sig: NodeJS.Signals) {
294	        self.signals.push(sig)
295	      },
296	      exited,
297	      get alive() { return alive },
298	      pid: undefined,
299	    }
300	  }
301	}
302	"}]},"parent_tool_use_id":"toolu_01X4nA1h5WNTjLJeBdjhkQqQ","session_id":"fdc14279-08b7-457c-9133-824e58d8aa23","uuid":"1381f196-6e43-430b-98e9-1391edec3a5e","timestamp":"2026-04-10T20:05:10.265Z"}

