2	import type { EventStorageAdapter } from './event-storage.js'
3	
4	export const DEFAULT_MAX_SIZE = 2000
5	
6	export interface EventLogOptions {
7	  maxSize?: number
8	  storage?: EventStorageAdapter
9	  /** Session ID for storage lookups. Required when recovering from storage
10	   *  with an empty in-memory buffer (server restart). */
11	  sessionId?: string
12	}
13	
14	export class EventLog {
15	  private events: SessionEvent[] = []
16	  private seq = 0
17	  private listeners = new Set<(event: SessionEvent) => void>()
18	  private maxSize: number
19	  private storage: EventStorageAdapter | null
20	  private sessionId: string | null
21	
22	  constructor(options?: EventLogOptions | number) {
23	    // Backwards compatible: accept a plain number (maxSize) or options object
24	    if (typeof options === 'number') {
25	      this.maxSize = options
26	      this.storage = null
27	      this.sessionId = null
28	    } else {
29	      this.maxSize = options?.maxSize ?? DEFAULT_MAX_SIZE
30	      this.storage = options?.storage ?? null
31	      this.sessionId = options?.sessionId ?? null
32	    }
33	
34	    // When recovering from storage, sync the seq counter so new appends
35	    // don't collide with existing events.
36	    if (this.storage && this.sessionId) {
37	      const tail = this.storage.read(this.sessionId, {
38	        beforeSeq: Number.MAX_SAFE_INTEGER,
39	        limit: 1,
40	      })
41	      if (tail.length > 0) {
42	        this.seq = tail[0].seq
43	      }
44	    }
45	  }
46	
47	  append(
48	    type: EventType,
49	    data: unknown,
50	    runId: string,
51	    sessionId: string,
52	    meta?: SessionEvent['meta'],
53	  ): SessionEvent {
54	    const event: SessionEvent = {
55	      sessionId,
56	      runId,
57	      seq: ++this.seq,
58	      timestamp: Date.now(),
59	      type,
60	      data,
61	      ...(meta ? { meta } : {}),
62	    }
63	    this.events.push(event)
64	    this.storage?.write(event)
65	    this.evict()
66	    for (const listener of this.listeners) listener(event)
67	    return event
68	  }
69	
70	  /**
71	   * Returns events after the given seq.
72	   * Checks in-memory first; falls back to storage for evicted events.
73	   */
74	  since(afterSeq: number): SessionEvent[] {
75	    if (this.events.length === 0 && !this.storage) return []
76	
77	    const earliest = this.events[0]?.seq ?? Infinity
78	
79	    // If requested seq is within the in-memory range, serve from memory.
80	    // Guard: only use the in-memory fast path when there ARE in-memory events.
81	    // After recovery from storage, memory is empty and earliest is Infinity —
82	    // we must fall through to the storage paths below.
83	    if (this.events.length > 0 && (afterSeq >= earliest || afterSeq === 0)) {
84	      return this.events.filter((e) => e.seq > afterSeq)
85	    }
86	
87	    // If storage exists, read the gap from storage + memory
88	    if (this.storage && this.events.length > 0) {
89	      const sessionId = this.events[0].sessionId
90	      const fromStorage = this.storage.read(sessionId, {
91	        afterSeq,
92	        beforeSeq: earliest,
93	      })
94	      const fromMemory = this.events.filter((e) => e.seq > afterSeq)
95	      return [...fromStorage, ...fromMemory]
96	    }
97	
98	    // If storage exists but memory is empty, read from storage using sessionId
99	    if (this.storage) {
100	      const sid = this.sessionId ?? this.events[0]?.sessionId
101	      if (sid) {
102	        return this.storage.read(sid, { afterSeq })
103	      }
104	      return []
105	    }
106	
107	    // No storage, events evicted — caller needs a reset
108	    return []
109	  }
110	
111	  /**
112	   * Returns true if the requested afterSeq is older than our earliest event
113	   * AND we can't serve from storage — meaning the caller needs a full reset.
114	   */
115	  needsReset(afterSeq: number): boolean {
116	    if (this.events.length === 0 && !this.storage) return false
117	    if (afterSeq === 0) return false
118	
119	    const earliest = this.events[0]?.seq ?? Infinity
120	
121	    // If storage exists, we can always serve historical events
122	    if (this.storage) return false
123	
124	    // No storage — check if requested seq is before our earliest in-memory event
125	    return afterSeq < earliest
126	  }
127	
128	  /**
129	   * Read events directly from storage (bypassing in-memory cache).
130	   * Useful for HTTP history endpoints. Returns empty if no storage adapter.
131	   */
132	  readFromStorage(sessionId: string, opts?: {
133	    afterSeq?: number
134	    beforeSeq?: number
135	    limit?: number
136	  }): SessionEvent[] {
137	    return this.storage?.read(sessionId, opts) ?? []
138	  }
139	
140	  /**
141	   * Count total events in storage for a session.
142	   * Returns in-memory count if no storage adapter.
143	   */
144	  countInStorage(sessionId: string): number {
145	    return this.storage?.count(sessionId) ?? this.events.length
146	  }
147	
148	  latest(): SessionEvent | null {
149	    return this.events[this.events.length - 1] ?? null
150	  }
151	
152	  all(): readonly SessionEvent[] {
153	    return this.events
154	  }
155	
156	  subscribe(cb: (event: SessionEvent) => void): () => void {
157	    this.listeners.add(cb)
158	    return () => {
159	      this.listeners.delete(cb)
160	    }
161	  }
162	
163	  get length(): number {
164	    return this.events.length
165	  }
166	
167	  get subscriberCount(): number {
168	    return this.listeners.size
169	  }
170	
171	  get earliestSeq(): number | null {
172	    return this.events[0]?.seq ?? null
173	  }
174	
175	  get hasStorage(): boolean {
176	    return this.storage !== null
177	  }
178	
179	  private evict(): void {
180	    if (this.events.length > this.maxSize) {
181	      const excess = this.events.length - this.maxSize
182	      this.events.splice(0, excess)
183	    }
184	  }
185	}
